16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "birth_date")
58	    private LocalDate birthDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "postcode")
76	    private String postcode;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    public void setEmail(String email) {
110	        this.email = email;
111	    }
112	
113	    public LocalDate getRegistrationDate() {
114	        return this.registrationDate;
115	    }
116	
117	    public void setRegistrationDate(LocalDate registrationDate) {
118	        this.registrationDate = registrationDate;
119	    }
120	
121	    public LocalDate getBirthDate() {
122	        return this.birthDate;
123	    }
124	
125	    public void setBirthDate(LocalDate birthDate) {
126	        this.birthDate = birthDate;
127	    }
128	
129	    public String getCustomerCode() {
130	        return this.customerCode;
131	    }
132	
133	    public void setCustomerCode(String customerCode) {
134	        this.customerCode = customerCode;
135	    }
136	
137	    public String getHouseholdId() {
138	        return this.householdId;
139	    }
140	
141	    public void setHouseholdId(String householdId) {
142	        this.householdId = householdId;
143	    }
144	
145	    public Integer getNamesakeCount() {
146	        return this.namesakeCount;
147	    }
148	
149	    public void setNamesakeCount(Integer namesakeCount) {
150	        this.namesakeCount = namesakeCount;
151	    }
152	
153	    public Boolean getBulkSignupWarning() {
154	        return this.bulkSignupWarning;
155	    }
156	
157	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
158	        this.bulkSignupWarning = bulkSignupWarning;
159	    }
160	
161	    public Integer getHouseholdSize() {
162	        return this.householdSize;
163	    }
164	
165	    public void setHouseholdSize(Integer householdSize) {
166	        this.householdSize = householdSize;
167	    }
168	
169	    public String getPostcode() {
170	        return this.postcode;
171	    }
172	
173	    public void setPostcode(String postcode) {
174	        this.postcode = postcode;
175	    }
176	
177	    /**
178	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
179	     * is the last two digits of the registration date's year (e.g. {@code "NSW-1A2B3C4D-M26"}).
180	     * Derived from the owner's own fields, so it stays consistent with them.
181	     */
182	    @Transient
183	    public String getMembershipNumber() {
184	        if (this.customerCode == null || this.registrationDate == null) {
185	            return null;
186	        }
187	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
188	    }
189	
190	    /**
191	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
192	     * over the digits of the customer code. Derived from the owner's own customer code,
193	     * so it stays consistent with it.
194	     */
195	    @Transient
196	    public Integer getCheckDigit() {
197	        if (this.customerCode == null) {
198	            return null;
199	        }
200	        return LuhnCheckDigit.of(this.customerCode);
201	    }
202	
203	    /**
204	     * The owner's membership level, a number from 1 to 3. Every owner starts at level 1;
205	     * one level is added when an email is on file and one more when the owner is unique
206	     * (namesake count of zero). The level is capped at 3, leaving level 4 reserved for
207	     * tenure. Derived from the owner's own fields, so it stays consistent with them.
208	     */
209	    @Transient
210	    public Integer getMembershipLevel() {
211	        int level = 1;
212	        boolean hasEmail = this.email != null && !this.email.isEmpty();
213	        if (hasEmail) {
214	            level++;
215	        }
216	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
217	        if (unique) {
218	            level++;
219	        }
220	        return Math.min(level, 3);
221	    }
222	
223	    /**
224	     * The owner's locality: the canonical region, taken as the region segment of the
225	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
226	     * consistent with the owner's identity. When no customer code has been assigned yet
227	     * it falls back to resolving the region directly from the postcode and city (see
228	     * {@link RegionResolver}), the same rule the customer code itself is built from.
229	     */
230	    @Transient
231	    public String getLocality() {
232	        if (this.customerCode != null) {
233	            int separator = this.customerCode.indexOf('-');
234	            if (separator > 0) {
235	                return this.customerCode.substring(0, separator);
236	            }
237	        }
238	        return RegionResolver.regionFor(this.postcode, this.city);
239	    }
240	
241	    /**
242	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
243	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
244	     * stays consistent with them.
245	     */
246	    @Transient
247	    public String getContactPreference() {
248	        boolean hasEmail = this.email != null && !this.email.isEmpty();
249	        return hasEmail ? "EMAIL" : "PHONE";
250	    }
251	
252	    /**
253	     * The owner's identity key: the single derived value used to detect duplicate owners,
254	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
255	     * Two owners are duplicates only when their whole identity keys are equal, so members
256	     * of one household (sharing a household id) but with different telephones stay distinct.
257	     * Derived from the owner's own fields, so it stays consistent with them.
258	     */
259	    @Transient
260	    public String getIdentityKey() {
261	        String telephonePart = this.telephone == null ? "" : this.telephone;
262	        String emailPart = this.email == null ? "" : this.email;
263	        String householdPart = this.householdId == null ? "" : this.householdId;
264	        return telephonePart + "|" + emailPart + "|" + householdPart;
265	    }
266	
267	    /**
268	     * The owner's age band relative to their registration date: {@code "MINOR"} when
269	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
270	     * Derived from the owner's own birth and registration dates, so it stays consistent
271	     * with them; null until a birth date is on file. See {@link AgeBand}.
272	     */
273	    @Transient
274	    public String getAgeBand() {
275	        if (this.birthDate == null || this.registrationDate == null) {
276	            return null;
277	        }
278	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
279	    }
280	
281	    /**
282	     * Normalize the registration date before persisting: default it to the server's
283	     * current date when none was supplied, then roll it forward onto a business day so
284	     * every newly persisted owner is registered on a weekday.
285	     */
286	    @PrePersist
287	    void normalizeRegistrationDate() {
288	        if (this.registrationDate == null) {
289	            this.registrationDate = LocalDate.now();
290	        }
291	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
292	    }
293	
294	    protected Set<Pet> getPetsInternal() {
295	        if (this.pets == null) {
296	            this.pets = new HashSet<>();
297	        }
298	        return this.pets;
299	    }
300	
301	    protected void setPetsInternal(Set<Pet> pets) {
302	        this.pets = pets;
303	    }
304	
305	    public List<Pet> getPets() {
306	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
307	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
308	        return Collections.unmodifiableList(sortedPets);
309	    }
310	
311	    public void setPets(List<Pet> pets) {
312	        this.pets = new HashSet<>(pets);
313	    }
314	
315	    public void addPet(Pet pet) {
316	        getPetsInternal().add(pet);
317	        pet.setOwner(this);
318	    }
319	
320	    /**
321	     * Return the Pet with the given name, or null if none found for this Owner.
322	     *
323	     * @param name to test
324	     * @return true if pet name is already in use
325	     */
326	    public Pet getPet(String name) {
327	        return getPet(name, false);
328	    }
329	
330	    /**
331	     * Return the Pet with the given name, or null if none found for this Owner.
332	     *
333	     * @param name to test
334	     * @return true if pet name is already in use
335	     */
336	    public Pet getPet(String name, boolean ignoreNew) {
337	        name = name.toLowerCase();
338	        for (Pet pet : getPetsInternal()) {
339	            if (!ignoreNew || !pet.isNew()) {
340	                String compName = pet.getName();
341	                compName = compName.toLowerCase();
342	                if (compName.equals(name)) {
343	                    return pet;
344	                }
345	            }
346	        }
347	        return null;
348	    }
349	
350	    public Pet getPet(Integer petId) {
351	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
352	    }
353	
354	    @Override
355	    public String toString() {
356	        return new ToStringCreator(this)
357	
358	            .append("id", this.getId())
359	            .append("new", this.isNew())
360	            .append("lastName", this.getLastName())
361	            .append("firstName", this.getFirstName())
362	            .append("address", this.address)
363	            .append("city", this.city)
364	            .append("telephone", this.telephone)
365	            .toString();
366	    }
367	}
