17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Optional;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.BusinessDay;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
44	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.service.OwnerAuditLogger;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Maximum number of owners allowed to be registered in a single city. A new owner
66	     * whose city already holds this many owners is rejected as a conflict.
67	     */
68	    private static final long MAX_OWNERS_PER_CITY = 50;
69	
70	    /**
71	     * Maximum number of owners allowed to be registered in a single day. Once this many
72	     * owners already carry today's registration date, a further create is rejected as
73	     * too many requests.
74	     */
75	    private static final long MAX_OWNERS_PER_DAY = 100;
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final TelephoneNormalizer telephoneNormalizer;
86	
87	    private final EmailNormalizer emailNormalizer;
88	
89	    private final AddressNormalizer addressNormalizer;
90	
91	    private final PostcodeValidator postcodeValidator;
92	
93	    private final OwnerAuditLogger ownerAuditLogger;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 EmailNormalizer emailNormalizer,
101	                                 AddressNormalizer addressNormalizer,
102	                                 PostcodeValidator postcodeValidator,
103	                                 OwnerAuditLogger ownerAuditLogger) {
104	        this.clinicService = clinicService;
105	        this.ownerMapper = ownerMapper;
106	        this.petMapper = petMapper;
107	        this.visitMapper = visitMapper;
108	        this.telephoneNormalizer = telephoneNormalizer;
109	        this.emailNormalizer = emailNormalizer;
110	        this.addressNormalizer = addressNormalizer;
111	        this.postcodeValidator = postcodeValidator;
112	        this.ownerAuditLogger = ownerAuditLogger;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        String address = addressNormalizer.normalize(owner.getAddress());
146	        if (addressNormalizer.isBlank(address)) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        owner.setAddress(address);
150	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
151	        if (e164Telephone.isEmpty()) {
152	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	        }
154	        String telephone = e164Telephone.get();
155	        String email = emailNormalizer.normalize(owner.getEmail());
156	        if (email != null && !emailNormalizer.isValid(email)) {
157	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	        }
159	        if (owner.getPostcode() != null && !postcodeValidator.isValid(owner.getPostcode(), owner.getCity())) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
163	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        LocalDate registrationDate = BusinessDay.rollForward(
167	            suppliedRegistrationDate == null ? LocalDate.now() : suppliedRegistrationDate);
168	        owner.setRegistrationDate(registrationDate);
169	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
170	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
171	        }
172	        owner.setTelephone(telephone);
173	        owner.setEmail(email);
174	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
175	            clinicService.shareHousehold(owner);
176	        }
177	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
178	            return new ResponseEntity<>(HttpStatus.CONFLICT);
179	        }
180	        // A single derived identity key now captures the telephone, email and household
181	        // duplicate checks: only an exact whole-key match with an existing owner is a
182	        // duplicate, so two household members with different telephones both remain valid.
183	        if (clinicService.existsOwnerByIdentityKey(owner.getIdentityKey())) {
184	            return new ResponseEntity<>(HttpStatus.CONFLICT);
185	        }
186	        this.clinicService.saveOwner(owner);
187	        this.ownerAuditLogger.logCreated(owner);
188	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
189	        headers.setLocation(UriComponentsBuilder.newInstance()
190	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
191	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
197	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
198	        if (currentOwner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
202	        if (e164Telephone.isEmpty()) {
203	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
204	        }
205	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
206	        if (email != null && !emailNormalizer.isValid(email)) {
207	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
208	        }
209	        String postcode = ownerFieldsDto.getPostcode();
210	        if (postcode != null && !postcodeValidator.isValid(postcode, ownerFieldsDto.getCity())) {
211	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
212	        }
213	        currentOwner.setAddress(ownerFieldsDto.getAddress());
214	        currentOwner.setCity(ownerFieldsDto.getCity());
215	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
216	        currentOwner.setLastName(ownerFieldsDto.getLastName());
217	        currentOwner.setTelephone(e164Telephone.get());
218	        currentOwner.setEmail(email);
219	        currentOwner.setPostcode(postcode);
220	        this.clinicService.saveOwner(currentOwner);
221	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Transactional
226	    @Override
227	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        this.clinicService.deleteOwner(owner);
233	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner == null) {
241	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	        }
243	        HttpHeaders headers = new HttpHeaders();
244	        Pet pet = petMapper.toPet(petFieldsDto);
245	        owner.setId(ownerId);
246	        pet.setOwner(owner);
247	        pet.getType().setName(null);
248	        this.clinicService.savePet(pet);
249	        PetDto petDto = petMapper.toPetDto(pet);
250	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
251	            .buildAndExpand(pet.getId()).toUri());
252	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
253	    }
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
258	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
259	        if (currentOwner != null) {
260	            Pet currentPet = this.clinicService.findPetById(petId);
261	            if (currentPet != null) {
262	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
263	                currentPet.setName(petFieldsDto.getName());
264	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
265	                this.clinicService.savePet(currentPet);
266	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
267	            }
268	        }
269	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
275	        HttpHeaders headers = new HttpHeaders();
276	        Visit visit = visitMapper.toVisit(visitFieldsDto);
277	        Pet pet = new Pet();
278	        pet.setId(petId);
279	        visit.setPet(pet);
280	        this.clinicService.saveVisit(visit);
281	        VisitDto visitDto = visitMapper.toVisitDto(visit);
282	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
283	            .buildAndExpand(visit.getId()).toUri());
284	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
285	    }
