245	    @Override
246	    @Transactional
247	    public void saveOwner(Owner owner) throws DataAccessException {
248	        if (owner.isNew()) {
249	            if (owner.getCustomerCode() == null) {
250	                owner.setCustomerCode(customerCodeGenerator.generate(
251	                    RegionResolver.regionFor(owner.getPostcode(), owner.getCity()),
252	                    owner.getTelephone(), owner.getLastName()));
253	            }
254	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
255	            owner.setBulkSignupWarning(
256	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
257	            owner.setHouseholdSize(householdSizeIncluding(owner));
258	        }
259	        ownerRepository.save(owner);
