263	    /**
264	     * Size of the household this new owner will belong to once persisted: the owners
265	     * already sharing its household id, plus the owner itself. An owner with no shared
266	     * household id stands alone, so its household size is one.
267	     */
268	    private int householdSizeIncluding(Owner owner) {
269	        if (owner.getHouseholdId() == null) {
270	            return 1;
271	        }
272	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
273	    }
274	
275	    /**
276	     * Count the existing owners that already share the given first and last name,
277	     * compared case-insensitively. Used to stamp a new owner's namesake count at
278	     * registration, before it is itself persisted.
279	     */
280	    private int countNamesakes(String firstName, String lastName) {
281	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
282	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
283	            .count();
284	    }
