311	    @Override
312	    @Transactional
313	    public String shareHousehold(Owner owner) throws DataAccessException {
314	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
315	        // Backfill the existing members so the whole household carries one shared id.
316	        householdMembers(owner.getLastName(), owner.getAddress()).stream()
317	            .filter(member -> !householdId.equals(member.getHouseholdId()))
318	            .forEach(member -> {
319	                member.setHouseholdId(householdId);
320	                ownerRepository.save(member);
321	            });
322	        owner.setHouseholdId(householdId);
323	        return householdId;
324	    }
325	
326	    /**
327	     * Return the existing owners that already occupy the household identified by the
328	     * given last name and address, i.e. that map to the same shared household id.
329	     */
330	    private List<Owner> householdMembers(String lastName, String address) {
331	        String householdId = householdIdGenerator.generate(lastName, address);
332	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
333	            .filter(owner -> householdId.equals(
334	                householdIdGenerator.generate(owner.getLastName(), owner.getAddress())))
335	            .toList();
336	    }
