350	    private <T> T findEntityById(Supplier<T> supplier) {
351	        try {
352	            return supplier.get();
353	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
354	            // Just ignore not found exceptions for Jdbc/Jpa realization
355	            return null;
356	        }
357	    }
